from collections import deque
def comps(g,color):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==color and (i,j) not in seen:
                q=deque([(i,j)]);seen.add((i,j));c=[]
                while q:
                    a,b=q.popleft();c.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==color and (x,y) not in seen:
                            seen.add((x,y));q.append((x,y))
                out.append(c)
    return out
def f(g):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r)
    sep=[i for i in range(h) if len(set(g[i]))==1]
    if not sep: return [row[:] for row in g]
    scol=g[sep[0]][0]
    seps_c=[j for j in range(w) if len({g[i][j] for i in range(h)})==1]
    others=[c for c in cnt if c!=scol]
    bg=max(others,key=lambda c:cnt[c])
    acc=[c for c in others if c!=bg][0]
    rb=list(zip([-1]+sep, sep+[h])); cb=list(zip([-1]+seps_c, seps_c+[w]))
    best=None;band=None
    for r0,r1 in rb:
        for c0,c1 in cb:
            for comp in comps(g,acc):
                rs=[a for a,b in comp];cs=[b for a,b in comp]
                area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
                # fill if component bbox fits entirely in band? check
                if all(r0<=a<r1 and c0<=b<c1 for a,b in comp):
                    key=area
                    if best is None or key>best: best=key;band=(r0,r1,c0,c1)
    if band is None: return [row[:] for row in g]
    r0,r1,c0,c1=band
    out=[row[:] for row in g]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1): out[i][j]=acc
    return out
