def cc(g,color):
    h=len(g);w=len(g[0]);seen=set();res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==color and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]==color and (x,y) not in seen:
                            seen.add((x,y));st.append((x,y))
                res.append(cells)
    return res
